}

TfLiteStatus PreluEval(TfLiteContext* context, TfLiteNode* node) {
  const TfLiteTensor* input = GetInput(context, node, 0);
  const TfLiteTensor* alpha = GetInput(context, node, 1);
  TfLiteTensor* output = GetOutput(context, node, 0);
  const PreluOpData* data = reinterpret_cast<PreluOpData*>(node->user_data);
  switch (input->type) {
    case kTfLiteFloat32: {
      if (kernel_type == kGenericOptimized) {
        tflite::ArithmeticParams op_params;
        bool need_broadcast = optimized_ops::ProcessBroadcastShapes(
            GetTensorShape(input), GetTensorShape(alpha), &op_params);
        if (need_broadcast) {
          optimized_ops::BroadcastPReluDispatch(
              op_params, GetTensorShape(input), GetTensorData<float>(input),
              GetTensorShape(alpha), GetTensorData<float>(alpha),
              GetTensorShape(output), GetTensorData<float>(output),
              ApplyPrelu<float>);
        } else {
          const int flat_size =
              MatchingElementsSize(GetTensorShape(input), GetTensorShape(alpha),
                                   GetTensorShape(output));
          optimized_ops::PReluElementWise(
              flat_size, op_params, GetTensorData<float>(alpha),
              GetTensorData<float>(input), GetTensorData<float>(output));
        }
      } else {
        if (data->requires_broadcast) {
          reference_ops::BroadcastBinaryFunction4DSlow<float, float, float>(
              GetTensorShape(input), GetTensorData<float>(input),
              GetTensorShape(alpha), GetTensorData<float>(alpha),
              GetTensorShape(output), GetTensorData<float>(output),
              ApplyPrelu<float>);
        } else {
          reference_ops::BinaryFunction<float, float, float>(
              GetTensorShape(input), GetTensorData<float>(input),
              GetTensorShape(alpha), GetTensorData<float>(alpha),
              GetTensorShape(output), GetTensorData<float>(output),
              ApplyPrelu<float>);
        }
      }
      return kTfLiteOk;
    } break;
    case kTfLiteUInt8: {
      PreluParams op_params;
      op_params.input_offset = -input->params.zero_point;
      op_params.alpha_offset = -alpha->params.zero_point;
      op_params.output_offset = output->params.zero_point;
      op_params.output_multiplier_1 = data->output_multiplier_1;
      op_params.output_shift_1 = data->output_shift_1;
      op_params.output_multiplier_2 = data->output_multiplier_2;
      op_params.output_shift_2 = data->output_shift_2;
      if (data->requires_broadcast) {
        reference_ops::BroadcastPrelu4DSlow(
            op_params, GetTensorShape(input), GetTensorData<uint8_t>(input),
            GetTensorShape(alpha), GetTensorData<uint8_t>(alpha),
            GetTensorShape(output), GetTensorData<uint8_t>(output));
      } else {
        reference_ops::Prelu(
            op_params, GetTensorShape(input), GetTensorData<uint8_t>(input),
            GetTensorShape(alpha), GetTensorData<uint8_t>(alpha),
            GetTensorShape(output), GetTensorData<uint8_t>(output));
      }
      return kTfLiteOk;
    } break;
    case kTfLiteInt8: {
      PreluParams op_params;
      op_params.input_offset = -input->params.zero_point;
      op_params.alpha_offset = -alpha->params.zero_point;
      op_params.output_offset = output->params.zero_point;
      op_params.output_multiplier_1 = data->output_multiplier_1;
      op_params.output_shift_1 = data->output_shift_1;
      op_params.output_multiplier_2 = data->output_multiplier_2;
      op_params.output_shift_2 = data->output_shift_2;
      if (data->requires_broadcast) {
        reference_ops::BroadcastPrelu4DSlow(
            op_params, GetTensorShape(input), GetTensorData<int8_t>(input),
            GetTensorShape(alpha), GetTensorData<int8_t>(alpha),
            GetTensorShape(output), GetTensorData<int8_t>(output));
      } else {
        reference_ops::Prelu(
            op_params, GetTensorShape(input), GetTensorData<int8_t>(input),
            GetTensorShape(alpha), GetTensorData<int8_t>(alpha),
            GetTensorShape(output), GetTensorData<int8_t>(output));
      }
      return kTfLiteOk;
    } break;
    default:
      TF_LITE_KERNEL_LOG(
          context,
          "Only float32 and uint8 and int8 are supported currently, got %d.",
          TfLiteTypeGetName(input->type));
      return kTfLiteError;
  }
}

static int parse_config(const char *var, const char *value, void *data)
{
	struct parse_config_parameter *me = data;
	struct submodule *submodule;
	struct strbuf name = STRBUF_INIT, item = STRBUF_INIT;
	int ret = 0;

	/* this also ensures that we only parse submodule entries */
	if (!name_and_item_from_var(var, &name, &item))
		return 0;

	submodule = lookup_or_create_by_name(me->cache,
					     me->gitmodules_sha1,
					     name.buf);

	if (!strcmp(item.buf, "path")) {
		if (!value)
			ret = config_error_nonbool(var);
		else if (!me->overwrite && submodule->path)
			warn_multiple_config(me->treeish_name, submodule->name,
					"path");
		else {
			if (submodule->path)
				cache_remove_path(me->cache, submodule);
			free((void *) submodule->path);
			submodule->path = xstrdup(value);
			cache_put_path(me->cache, submodule);
		}
	} else if (!strcmp(item.buf, "fetchrecursesubmodules")) {
		/* when parsing worktree configurations we can die early */
		int die_on_error = is_null_sha1(me->gitmodules_sha1);
		if (!me->overwrite &&
		    submodule->fetch_recurse != RECURSE_SUBMODULES_NONE)
			warn_multiple_config(me->treeish_name, submodule->name,
					"fetchrecursesubmodules");
		else
			submodule->fetch_recurse = parse_fetch_recurse(
								var, value,
								die_on_error);
	} else if (!strcmp(item.buf, "ignore")) {
		if (!value)
			ret = config_error_nonbool(var);
		else if (!me->overwrite && submodule->ignore)
			warn_multiple_config(me->treeish_name, submodule->name,
					"ignore");
		else if (strcmp(value, "untracked") &&
			 strcmp(value, "dirty") &&
			 strcmp(value, "all") &&
			 strcmp(value, "none"))
			warning("Invalid parameter '%s' for config option "
					"'submodule.%s.ignore'", value, name.buf);
		else {
			free((void *) submodule->ignore);
			submodule->ignore = xstrdup(value);
		}
	} else if (!strcmp(item.buf, "url")) {
		if (!value) {
			ret = config_error_nonbool(var);
		} else if (looks_like_command_line_option(value)) {
			warn_command_line_option(var, value);
		} else if (!me->overwrite && submodule->url) {
			warn_multiple_config(me->treeish_name, submodule->name,
					"url");
		} else {
			free((void *) submodule->url);
			submodule->url = xstrdup(value);
		}
	} else if (!strcmp(item.buf, "update")) {
		if (!value)
			ret = config_error_nonbool(var);
		else if (!me->overwrite &&
			 submodule->update_strategy.type != SM_UPDATE_UNSPECIFIED)
			warn_multiple_config(me->treeish_name, submodule->name,
					     "update");
		else if (parse_submodule_update_strategy(value,
			 &submodule->update_strategy) < 0)
				die(_("invalid value for %s"), var);
	} else if (!strcmp(item.buf, "shallow")) {
		if (!me->overwrite && submodule->recommend_shallow != -1)
			warn_multiple_config(me->treeish_name, submodule->name,
					     "shallow");
		else
			submodule->recommend_shallow =
				git_config_bool(var, value);
	} else if (!strcmp(item.buf, "branch")) {
		if (!me->overwrite && submodule->branch)
			warn_multiple_config(me->treeish_name, submodule->name,
					     "branch");
		else {
			free((void *)submodule->branch);
			submodule->branch = xstrdup(value);
		}
	}

	strbuf_release(&name);
	strbuf_release(&item);

	return ret;
}

static void io_req_drop_files(struct io_kiocb *req)
{
	struct io_ring_ctx *ctx = req->ctx;
	unsigned long flags;

	spin_lock_irqsave(&ctx->inflight_lock, flags);
	list_del(&req->inflight_entry);
	if (waitqueue_active(&ctx->inflight_wait))
		wake_up(&ctx->inflight_wait);
	spin_unlock_irqrestore(&ctx->inflight_lock, flags);
	req->flags &= ~REQ_F_INFLIGHT;
	put_files_struct(req->work.files);
	req->work.files = NULL;
}

xps_true_callback_glyph_name(gs_font *pfont, gs_glyph glyph, gs_const_string *pstr)
{
    /* This function is copied verbatim from plfont.c */

    int table_length;
    int table_offset;

    ulong format;
    int numGlyphs;
    uint glyph_name_index;
    const byte *postp; /* post table pointer */

    if (glyph >= GS_MIN_GLYPH_INDEX) {
        glyph -= GS_MIN_GLYPH_INDEX;
    }

    /* guess if the font type is not truetype */
    if ( pfont->FontType != ft_TrueType )
    {
        glyph -= 29;
        if (glyph < 258 )
        {
            pstr->data = (byte*) pl_mac_names[glyph];
            pstr->size = strlen((char*)pstr->data);
            return 0;
        }
        else
        {
            return gs_throw1(-1, "glyph index %lu out of range", (ulong)glyph);
        }
    }

    table_offset = xps_find_sfnt_table((xps_font_t*)pfont->client_data, "post", &table_length);

    /* no post table */
    if (table_offset < 0)
        return gs_throw(-1, "no post table");

    /* this shoudn't happen but... */
    if ( table_length == 0 )
        return gs_throw(-1, "zero-size post table");

    ((gs_font_type42 *)pfont)->data.string_proc((gs_font_type42 *)pfont,
                                                table_offset, table_length, &postp);
    format = u32(postp);

    /* Format 1.0 (mac encoding) is a simple table see the TT spec.
     * We don't implement this because we don't see it in practice.
     * Format 2.5 is deprecated.
     * Format 3.0 means that there is no post data in the font file.
     * We see this a lot but can't do much about it.
     * The only format we support is 2.0.
     */
    if ( format != 0x20000 )
    {
        /* Invent a name if we don't know the table format. */
        char buf[32];
        gs_sprintf(buf, "glyph%d", (int)glyph);
        pstr->data = (byte*)buf;
        pstr->size = strlen((char*)pstr->data);
        return 0;
    }

    /* skip over the post header */
    numGlyphs = (int)u16(postp + 32);
    if ((int)glyph > numGlyphs - 1)
    {
        return gs_throw1(-1, "glyph index %lu out of range", (ulong)glyph);
    }

    /* glyph name index starts at post + 34 each entry is 2 bytes */
    glyph_name_index = u16(postp + 34 + (glyph * 2));

    /* this shouldn't happen */
    if ( glyph_name_index > 0x7fff )
        return gs_throw(-1, "post table format error");

    /* mac easy */
    if ( glyph_name_index < 258 )
    {
        // dmprintf2(pfont->memory, "glyph name (mac) %d = %s\n", glyph, pl_mac_names[glyph_name_index]);
        pstr->data = (byte*) pl_mac_names[glyph_name_index];
        pstr->size = strlen((char*)pstr->data);
        return 0;
    }

    /* not mac */
    else
    {
        byte *mydata;

        /* and here's the tricky part */
        const byte *pascal_stringp = postp + 34 + (numGlyphs * 2);

        /* 0 - 257 lives in the mac table above */
        glyph_name_index -= 258;

        /* The string we want is the index'th pascal string,
         * so we "hop" to each length byte "index" times. */
        while (glyph_name_index > 0)
        {
            pascal_stringp += ((int)(*pascal_stringp)+1);
            glyph_name_index--;
        }

        /* length byte */
        pstr->size = (int)(*pascal_stringp);

        /* + 1 is for the length byte */
        pstr->data = pascal_stringp + 1;

        /* sanity check */
        if ( pstr->data + pstr->size > postp + table_length || pstr->data - 1 < postp)
            return gs_throw(-1, "data out of range");

        /* sigh - we have to allocate a copy of the data - by the
         * time a high level device makes use of it the font data
         * may be freed. This is a necessary leak. */
        mydata = gs_alloc_bytes(pfont->memory, pstr->size + 1, "glyph to name");
        if ( mydata == 0 )
            return -1;
        memcpy(mydata, pascal_stringp + 1, pstr->size);
        pstr->data = mydata;

        mydata[pstr->size] = 0;

        return 0;
    }
}

void operator()(OpKernelContext* ctx, const CPUDevice& d, int64 num_batches,
                int64 samples_per_batch, int64 num_elements,
                typename TTypes<T>::ConstFlat means,
                typename TTypes<T>::ConstFlat stddevs,
                typename TTypes<T>::ConstFlat minvals,
                typename TTypes<T>::ConstFlat maxvals,
                const random::PhiloxRandom& gen,
                typename TTypes<T>::Flat output) {
  // The randn rejection sampling is used when the mean and at least this many
  // standard deviations are inside the bounds.
  // The uniform proposal samplers become less efficient as the bounds are
  // further from the mean, the reverse is true for the randn sampler.
  // This number was chosen by empirical benchmarking. If modified, the
  // benchmarks in parameterized_truncated_normal_op_test should also be
  // changed.
  const T kStdDevsInsideBoundsToUseRandnSampler = T(1.3);
  auto worker_threads = *(ctx->device()->tensorflow_cpu_worker_threads());

  auto do_work = [samples_per_batch, num_elements, &ctx, &means, &stddevs,
                  &minvals, &maxvals, &gen, &output,
                  kStdDevsInsideBoundsToUseRandnSampler](int start_batch,
                                                         int limit_batch) {
    // Capturing "gen" by-value would only make a copy for the _shared_
    // lambda.  Since we want to let each worker have its own copy, we pass
    // "gen" by reference and explicitly do a copy assignment here.
    random::PhiloxRandom gen_copy = gen;
    // Skip takes units of 128 bytes.  +3 is so rounding doesn't lead to
    // us using the same state in different batches.
    // The sample from each iteration uses 2 random numbers.
    gen_copy.Skip(start_batch * 2 * kMaxIterations * (samples_per_batch + 3) /
                  4);
    using Uniform = random::UniformDistribution<random::PhiloxRandom, T>;
    Uniform dist;
    using Normal = random::NormalDistribution<random::PhiloxRandom, T>;
    Normal normal_dist;

    // Vectorized intermediate calculations for uniform rejection sampling.
    // We always generate at most 4 samples.
    Eigen::array<T, 4> z;
    Eigen::array<T, 4> g;

    for (int64 b = start_batch; b < limit_batch; ++b) {
      // We are passed a flat array for each of the parameter tensors.
      // The input is either a scalar broadcasted to all batches or a vector
      // with length num_batches, but the scalar becomes an array of length 1.
      T mean = means((means.dimension(0) == 1) ? 0 : b);
      T stddev = stddevs((stddevs.dimension(0) == 1) ? 0 : b);
      T minval = minvals((minvals.dimension(0) == 1) ? 0 : b);
      T maxval = maxvals((maxvals.dimension(0) == 1) ? 0 : b);

      // The last batch can be short, if we adjusted num_batches and
      // samples_per_batch.
      const int64 limit_sample =
          std::min((b + 1) * samples_per_batch, num_elements);
      int64 sample = b * samples_per_batch;

      // On GPU, this check will just fill samples with NAN if it fails.
      OP_REQUIRES(ctx,
                  stddev > T(0) && minval < maxval &&
                      (Eigen::numext::isfinite(minval) ||
                       Eigen::numext::isfinite(maxval)),
                  errors::InvalidArgument("Invalid parameters"));

      int num_iterations = 0;

      // If possible, make one-sided bound be the lower bound, or make both
      // bounds positive. Otherwise, the bounds are on either side of the
      // mean.
      if ((Eigen::numext::isinf(minval) && minval < T(0)) || maxval < mean) {
        // Reverse all calculations. normMin and normMax will be flipped.
        std::swap(minval, maxval);
        stddev = -stddev;
      }

      // Calculate normalized samples, then convert them.
      const T normMin = (minval - mean) / stddev;
      const T normMax = (maxval - mean) / stddev;

      // Determine the method to use.
      const T sqrtFactor = Eigen::numext::sqrt((normMin * normMin) + T(4));
      const T cutoff =
          T(2) *
          Eigen::numext::exp(T(0.5) +
                             (normMin * (normMin - sqrtFactor)) / T(4)) /
          (normMin + sqrtFactor);
      const T diff = normMax - normMin;

      if (((normMin < -kStdDevsInsideBoundsToUseRandnSampler) &&
           (normMax >= T(0.))) ||
          ((normMax > kStdDevsInsideBoundsToUseRandnSampler) &&
           (normMin <= T(0.)))) {
        // If the bounds are a least 3 standard deviations from the mean
        // on at least one side then we rejection sample by sampling
        // from the normal distribution and rejecting samples outside
        // the bounds.
        // Under this condition the acceptance rate per iteration should
        // always be ~ 50%. This sampler is more efficient (and more
        // numerically stable when one or both bounds is far from the mean).

        while (sample < limit_sample) {
          const auto randn_sample = normal_dist(&gen_copy);
          const int size = randn_sample.size();

          for (int i = 0; i < size; i++) {
            if ((randn_sample[i] >= normMin) &&
                (randn_sample[i] <= normMax)) {
              output(sample) = randn_sample[i] * stddev + mean;
              sample++;
              if (sample >= limit_sample) {
                break;
              }
              num_iterations = 0;
            } else {
              num_iterations++;
              if (num_iterations > kMaxIterations) {
                // This should never occur because this sampler should
                // (by the selection criteria above) be used if at least 3
                // standard deviations of one side of the distribution
                // is within the limits (so acceptance probability per
                // iterations >~ 1/2 per iteration).
                LOG(ERROR) << "TruncatedNormal randn rejection sampler "
                           << "exceeded maximum iterations for "
                           << "normMin=" << normMin << " normMax=" << normMax
                           << " kMaxIterations=" << kMaxIterations;
                ctx->SetStatus(errors::Internal(
                    "TruncatedNormal randn rejection sampler failed to accept"
                    " a sample."));
                return;
              }
            }
          }
        }
      } else if (diff < cutoff) {
        // Sample from a uniform distribution on [normMin, normMax].

        const T plusFactor = (normMin < T(0)) ? T(0) : normMin * normMin;

        while (sample < limit_sample) {
          const auto rand = dist(&gen_copy);
          const int size = rand.size();
          // NOTE(ringwalt): These loops seem to only generate packed AVX
          // instructions for float32.
          for (int i = 0; i < size; i++) {
            z[i] = rand[i] * diff + normMin;
          }
          for (int i = 0; i < size; i++) {
            g[i] = (plusFactor - z[i] * z[i]) / T(2.0);
          }

          const auto u = dist(&gen_copy);
          for (int i = 0; i < size; i++) {
            auto accept = u[i] <= Eigen::numext::exp(g[i]);
            if (accept || num_iterations + 1 >= kMaxIterations) {
              // Accept the sample z.
              // If we run out of iterations, just use the current uniform
              // sample, but emit a warning.
              // TODO(jjhunt) For small entropies (relative to the bounds),
              // this sampler is poor and may take many iterations since
              // the proposal distribution is the uniform distribution
              // U(lower_bound, upper_bound).
              if (!accept) {
                LOG(ERROR) << "TruncatedNormal uniform rejection sampler "
                           << "exceeded max iterations. Sample may contain "
                           << "outliers.";
                ctx->SetStatus(errors::Internal(
                    "TruncatedNormal uniform rejection sampler failed to "
                    " accept a sample."));
                return;
              }
              output(sample) = z[i] * stddev + mean;
              sample++;
              if (sample >= limit_sample) {
                break;
              }
              num_iterations = 0;
            } else {
              num_iterations++;
            }
          }
        }
      } else {
        // Sample from an exponential distribution with alpha maximizing
        // acceptance probability, offset by normMin from the origin.
        // Accept only if less than normMax.
        const T alpha =
            (normMin + Eigen::numext::sqrt((normMin * normMin) + T(4))) /
            T(2);
        while (sample < limit_sample) {
          auto rand = dist(&gen_copy);
          const int size = rand.size();
          int i = 0;
          while (i < size) {
            const T z = -Eigen::numext::log(rand[i]) / alpha + normMin;
            i++;
            const T x = normMin < alpha ? alpha - z : normMin - alpha;
            const T g = Eigen::numext::exp(-x * x / T(2.0));
            const T u = rand[i];
            i++;
            auto accept = (u <= g && z < normMax);
            if (accept || num_iterations + 1 >= kMaxIterations) {
              if (!accept) {
                LOG(ERROR) << "TruncatedNormal exponential distribution "
                           << "rejection sampler exceeds max iterations. "
                           << "Sample may contain outliers.";
                ctx->SetStatus(errors::Internal(
                    "TruncatedNormal exponential distribution rejection"
                    " sampler failed to accept a sample."));
                return;
              }
              output(sample) = z * stddev + mean;
              sample++;
              if (sample >= limit_sample) {
                break;
              }
              num_iterations = 0;
            } else {
              num_iterations++;
            }
          }
        }
      }
    }
  };
  // The cost of the initial calculations for the batch.
  const int64 batchInitCost =
      // normMin, normMax
      (Eigen::TensorOpCost::AddCost<T>() +
       Eigen::TensorOpCost::MulCost<T>()) *
          2
      // sqrtFactor
      + Eigen::TensorOpCost::AddCost<T>() +
      Eigen::TensorOpCost::MulCost<T>() +
      Eigen::internal::functor_traits<
          Eigen::internal::scalar_sqrt_op<T>>::Cost
      // cutoff
      + Eigen::TensorOpCost::MulCost<T>() * 4 +
      Eigen::internal::functor_traits<Eigen::internal::scalar_exp_op<T>>::Cost
      // diff
      + Eigen::TensorOpCost::AddCost<T>();
  const int64 uniformSampleCost =
      random::PhiloxRandom::kElementCost +
      random::UniformDistribution<random::PhiloxRandom, T>::kElementCost;
  // The cost of a single uniform sampling round.
  const int64 uniformRejectionSamplingCost =
      uniformSampleCost + Eigen::TensorOpCost::MulCost<T>() +
      Eigen::TensorOpCost::AddCost<T>() +
      Eigen::TensorOpCost::MulCost<T>() * 2 +
      Eigen::TensorOpCost::AddCost<T>() + uniformSampleCost +
      Eigen::internal::functor_traits<
          Eigen::internal::scalar_exp_op<T>>::Cost +
      Eigen::TensorOpCost::MulCost<T>() + Eigen::TensorOpCost::AddCost<T>();
  // Estimate the cost for an entire batch.
  // Assume we use uniform sampling, and accept the 2nd sample on average.
  const int64 batchCost =
      batchInitCost + uniformRejectionSamplingCost * 2 * samples_per_batch;
  Shard(worker_threads.num_threads, worker_threads.workers, num_batches,
        batchCost, do_work);
}

load_image (const gchar  *filename,
            GError      **error)
{
  FILE *f;
  struct stat st;
  char buf[32];
  PSPimage ia;
  guint32 block_init_len, block_total_len;
  long block_start;
  PSPBlockID id = -1;
  gint block_number;

  gint32 image_ID = -1;

  if (g_stat (filename, &st) == -1)
    return -1;

  f = g_fopen (filename, "rb");
  if (f == NULL)
    {
      g_set_error (error, G_FILE_ERROR, g_file_error_from_errno (errno),
                   _("Could not open '%s' for reading: %s"),
                   gimp_filename_to_utf8 (filename), g_strerror (errno));
      return -1;
    }

  /* Read the PSP File Header and determine file version */
  if (fread (buf, 32, 1, f) < 1
      || fread (&psp_ver_major, 2, 1, f) < 1
      || fread (&psp_ver_minor, 2, 1, f) < 1)
    {
      g_message ("Error reading file header");
      goto error;
    }

  if (memcmp (buf, "Paint Shop Pro Image File\n\032\0\0\0\0\0", 32) != 0)
    {
      g_message ("Incorrect file signature");
      goto error;
    }

  psp_ver_major = GUINT16_FROM_LE (psp_ver_major);
  psp_ver_minor = GUINT16_FROM_LE (psp_ver_minor);

  /* I only have the documentation for file format version 3.0,
   * but PSP 6 writes version 4.0. Let's hope it's backwards compatible.
   * Earlier versions probably don't have all the fields I expect
   * so don't accept those.
   */
  if (psp_ver_major < 3)
    {
      g_message ("Unsupported PSP file format version "
                 "%d.%d, only knows 3.0 (and later?)",
                 psp_ver_major, psp_ver_minor);
      goto error;
    }
  else if ((psp_ver_major == 3)
        || (psp_ver_major == 4)
        || (psp_ver_major == 5)
        || (psp_ver_major == 6))
    ; /* OK */
  else
    {
      g_message ("Unsupported PSP file format version %d.%d",
                 psp_ver_major, psp_ver_minor);
      goto error;
    }

  /* Read all the blocks */
  block_number = 0;

  IFDBG(3) g_message ("size = %d", (int)st.st_size);
  while (ftell (f) != st.st_size
         && (id = read_block_header (f, &block_init_len,
                                     &block_total_len)) != -1)
    {
      block_start = ftell (f);

      if (id == PSP_IMAGE_BLOCK)
        {
          if (block_number != 0)
            {
              g_message ("Duplicate General Image Attributes block");
              goto error;
            }
          if (read_general_image_attribute_block (f, block_init_len,
                                                  block_total_len, &ia) == -1)
            {
              goto error;
            }

          IFDBG(2) g_message ("%d dpi %dx%d %s",
                              (int) ia.resolution,
                              ia.width, ia.height,
                              compression_name (ia.compression));

          image_ID = gimp_image_new (ia.width, ia.height,
                                     ia.grayscale ? GIMP_GRAY : GIMP_RGB);
          if (image_ID == -1)
            {
              goto error;
            }

          gimp_image_set_filename (image_ID, filename);

          gimp_image_set_resolution (image_ID, ia.resolution, ia.resolution);
        }
      else
        {
          if (block_number == 0)
            {
              g_message ("Missing General Image Attributes block");
              goto error;
            }

          switch (id)
            {
            case PSP_CREATOR_BLOCK:
              if (read_creator_block (f, image_ID, block_total_len, &ia) == -1)
                goto error;
              break;

            case PSP_COLOR_BLOCK:
              break;            /* Not yet implemented */

            case PSP_LAYER_START_BLOCK:
              if (read_layer_block (f, image_ID, block_total_len, &ia) == -1)
                goto error;
              break;

            case PSP_SELECTION_BLOCK:
              break;            /* Not yet implemented */

            case PSP_ALPHA_BANK_BLOCK:
              break;            /* Not yet implemented */

            case PSP_THUMBNAIL_BLOCK:
              break;            /* No use for it */

            case PSP_EXTENDED_DATA_BLOCK:
              break;            /* Not yet implemented */

            case PSP_TUBE_BLOCK:
              if (read_tube_block (f, image_ID, block_total_len, &ia) == -1)
                goto error;
              break;

            case PSP_COMPOSITE_IMAGE_BANK_BLOCK:
              break;            /* Not yet implemented */

            case PSP_LAYER_BLOCK:
            case PSP_CHANNEL_BLOCK:
            case PSP_ALPHA_CHANNEL_BLOCK:
            case PSP_ADJUSTMENT_EXTENSION_BLOCK:
            case PSP_VECTOR_EXTENSION_BLOCK:
            case PSP_SHAPE_BLOCK:
            case PSP_PAINTSTYLE_BLOCK:
            case PSP_COMPOSITE_ATTRIBUTES_BLOCK:
            case PSP_JPEG_BLOCK:
              g_message ("Sub-block %s should not occur "
                         "at main level of file",
                         block_name (id));
              break;

            default:
              g_message ("Unrecognized block id %d", id);
              break;
            }
        }

      if (block_start + block_total_len >= st.st_size)
        break;

      if (try_fseek (f, block_start + block_total_len, SEEK_SET) < 0)
        goto error;

      block_number++;
    }

  if (id == -1)
    {
    error:
      fclose (f);
      if (image_ID != -1)
        gimp_image_delete (image_ID);
      return -1;
    }

  fclose (f);

  return image_ID;
}

