            arg1 = compile(ss,s,depth1,0,bloc_flags);
            arg2 = compile(s + 1,se,depth1,0,bloc_flags);
            p2 = _cimg_mp_size(arg2);
            if (p2>0 && (ulongT)_cimg_mp_size(arg1)==(ulongT)p2*p2) { // Particular case of matrix multiplication
