        ret = handle_gid_request(req->request_type, req->data.posix_gid.gid,
                                 req->data.posix_uid.domain_name, berval);

        break;
    case INP_SID:
        ret = handle_sid_request(req->request_type, req->data.sid, berval);
        break;
