bool run(OperationContext* opCtx,
         const string& dbname,
         const BSONObj& cmdObj,
         BSONObjBuilder& result) {
    std::string userNameString;
    std::vector<RoleName> roles;
    Status status = auth::parseRolePossessionManipulationCommands(
        cmdObj, "grantRolesToUser", dbname, &userNameString, &roles);
    if (!status.isOK()) {
        return appendCommandStatus(result, status);
    }

    ServiceContext* serviceContext = opCtx->getClient()->getServiceContext();
    stdx::lock_guard<stdx::mutex> lk(getAuthzDataMutex(serviceContext));

    AuthorizationManager* authzManager = AuthorizationManager::get(serviceContext);
    status = requireAuthSchemaVersion26Final(opCtx, authzManager);
    if (!status.isOK()) {
        return appendCommandStatus(result, status);
    }

    UserName userName(userNameString, dbname);
    unordered_set<RoleName> userRoles;
    status = getCurrentUserRoles(opCtx, authzManager, userName, &userRoles);
    if (!status.isOK()) {
        return appendCommandStatus(result, status);
    }

    for (vector<RoleName>::iterator it = roles.begin(); it != roles.end(); ++it) {
        RoleName& roleName = *it;
        BSONObj roleDoc;
        status = authzManager->getRoleDescription(opCtx, roleName, &roleDoc);
        if (!status.isOK()) {
            return appendCommandStatus(result, status);
        }

        userRoles.insert(roleName);
    }

    audit::logGrantRolesToUser(Client::getCurrent(), userName, roles);
    BSONArray newRolesBSONArray = roleSetToBSONArray(userRoles);
    status = updatePrivilegeDocument(
        opCtx, userName, BSON("$set" << BSON("roles" << newRolesBSONArray)));
    // Must invalidate even on bad status - what if the write succeeded but the GLE failed?
    authzManager->invalidateUserByName(userName);
    return appendCommandStatus(result, status);
}

MagickExport MagickBooleanType SetImageRegistry(const RegistryType type,
  const char *key,const void *value,ExceptionInfo *exception)
{
  MagickBooleanType
    status;

  RegistryInfo
    *registry_info;

  void
    *clone_value;

  if (IsEventLogging() != MagickFalse)
    (void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",key);
  if (value == (const void *) NULL)
    return(MagickFalse);
  clone_value=(void *) NULL;
  switch (type)
  {
    case StringRegistryType:
    default:
    {
      const char
        *string;

      string=(const char *) value;
      clone_value=(void *) ConstantString(string);
      break;
    }
    case ImageRegistryType:
    {
      const Image
        *image;

      image=(const Image *) value;
      if (image->signature != MagickCoreSignature)
        {
          (void) ThrowMagickException(exception,GetMagickModule(),RegistryError,
            "UnableToSetRegistry","%s",key);
          return(MagickFalse);
        }
      clone_value=(void *) CloneImageList(image,exception);
      break;
    }
    case ImageInfoRegistryType:
    {
      const ImageInfo
        *image_info;

      image_info=(const ImageInfo *) value;
      if (image_info->signature != MagickCoreSignature)
        {
          (void) ThrowMagickException(exception,GetMagickModule(),RegistryError,
            "UnableToSetRegistry","%s",key);
          return(MagickFalse);
        }
      clone_value=(void *) CloneImageInfo(image_info);
      break;
    }
  }
  if (clone_value == (void *) NULL)
    return(MagickFalse);
  registry_info=(RegistryInfo *) AcquireMagickMemory(sizeof(*registry_info));
  if (registry_info == (RegistryInfo *) NULL)
    ThrowFatalException(ResourceLimitFatalError,"MemoryAllocationFailed");
  (void) ResetMagickMemory(registry_info,0,sizeof(*registry_info));
  registry_info->type=type;
  registry_info->value=clone_value;
  registry_info->signature=MagickCoreSignature;
  if (registry == (SplayTreeInfo *) NULL)
    {
      if (registry_semaphore == (SemaphoreInfo *) NULL)
        ActivateSemaphoreInfo(&registry_semaphore);
      LockSemaphoreInfo(registry_semaphore);
      if (registry == (SplayTreeInfo *) NULL)
        registry=NewSplayTree(CompareSplayTreeString,RelinquishMagickMemory,
          DestroyRegistryNode);
      UnlockSemaphoreInfo(registry_semaphore);
    }
  status=AddValueToSplayTree(registry,ConstantString(key),registry_info);
  return(status);
}

