selReadStream(FILE  *fp)
{
char    *selname;
char     linebuf[L_BUF_SIZE];
l_int32  sy, sx, cy, cx, i, j, version, ignore;
SEL     *sel;

    PROCNAME("selReadStream");

    if (!fp)
        return (SEL *)ERROR_PTR("stream not defined", procName, NULL);

    if (fscanf(fp, "  Sel Version %d\n", &version) != 1)
        return (SEL *)ERROR_PTR("not a sel file", procName, NULL);
    if (version != SEL_VERSION_NUMBER)
        return (SEL *)ERROR_PTR("invalid sel version", procName, NULL);

    if (fgets(linebuf, L_BUF_SIZE, fp) == NULL)
        return (SEL *)ERROR_PTR("error reading into linebuf", procName, NULL);
    selname = stringNew(linebuf);
    sscanf(linebuf, "  ------  %s  ------", selname);

    if (fscanf(fp, "  sy = %d, sx = %d, cy = %d, cx = %d\n",
            &sy, &sx, &cy, &cx) != 4) {
        LEPT_FREE(selname);
        return (SEL *)ERROR_PTR("dimensions not read", procName, NULL);
    }

    if ((sel = selCreate(sy, sx, selname)) == NULL) {
        LEPT_FREE(selname);
        return (SEL *)ERROR_PTR("sel not made", procName, NULL);
    }
    selSetOrigin(sel, cy, cx);

    for (i = 0; i < sy; i++) {
        ignore = fscanf(fp, "    ");
        for (j = 0; j < sx; j++)
            ignore = fscanf(fp, "%1d", &sel->data[i][j]);
        ignore = fscanf(fp, "\n");
    }
    ignore = fscanf(fp, "\n");

    LEPT_FREE(selname);
    return sel;
}

void Compute(OpKernelContext* ctx) override {
  const Tensor& indices = ctx->input(0);
  const auto values = ctx->input(1).flat<Tidx>();
  const Tensor& dense_shape = ctx->input(2);
  const Tensor& size_t = ctx->input(3);
  const auto weights = ctx->input(4).flat<T>();
  const int64_t weights_size = weights.size();

  Tidx size = size_t.scalar<Tidx>()();
  OP_REQUIRES(
      ctx, size >= 0,
      errors::InvalidArgument("size (", size, ") must be non-negative"));

  bool is_1d = dense_shape.NumElements() == 1;

  Tensor* out_t;
  functor::SetZeroFunctor<Device, T> fill;
  if (is_1d) {
    OP_REQUIRES_OK(ctx, ctx->allocate_output(0, TensorShape({size}), &out_t));
    auto out = out_t->flat<T>();
    fill(ctx->eigen_device<Device>(), out);
    if (binary_output_) {
      OP_REQUIRES_OK(ctx,
                     functor::BincountFunctor<Device, Tidx, T, true>::Compute(
                         ctx, values, weights, out, size));
    } else {
      OP_REQUIRES_OK(
          ctx, functor::BincountFunctor<Device, Tidx, T, false>::Compute(
                   ctx, values, weights, out, size));
    }
  } else {
    const auto shape = dense_shape.flat<int64_t>();
    const int64_t num_rows = shape(0);
    OP_REQUIRES_OK(
        ctx, ctx->allocate_output(0, TensorShape({num_rows, size}), &out_t));
    const auto out = out_t->matrix<T>();
    fill(ctx->eigen_device<Device>(), out_t->flat<T>());
    const auto indices_mat = indices.matrix<int64_t>();
    for (int64_t i = 0; i < indices_mat.dimension(0); ++i) {
      const int64_t batch = indices_mat(i, 0);
      const Tidx bin = values(i);
      if (bin < size) {
        if (binary_output_) {
          out(batch, bin) = T(1);
        } else {
          if (weights_size) {
            out(batch, bin) += weights(i);
          } else {
            out(batch, bin) += T(1);
          }
        }
      }
    }
  }
}

int Init_v9(void) {
int i;

	output_templates = NULL;

	cache.lookup_info	    = (struct element_param_s *)calloc(65536, sizeof(struct element_param_s));
	cache.common_extensions = (uint32_t *)malloc((Max_num_extensions+1)*sizeof(uint32_t));
	if ( !cache.common_extensions || !cache.lookup_info ) {
		syslog(LOG_ERR, "Process_v9: Panic! malloc(): %s line %d: %s", __FILE__, __LINE__, strerror (errno));
		return 0;
	}

	// init the helper element table
	for (i=1; v9_element_map[i].id != 0; i++ ) {
		uint32_t Type = v9_element_map[i].id;
		// multiple same type - save first index only
		// iterate through same Types afterwards
		if ( cache.lookup_info[Type].index == 0 ) 
			cache.lookup_info[Type].index  = i;
	}
	cache.max_v9_elements = i;

	syslog(LOG_DEBUG,"Init v9: Max number of v9 tags: %u", cache.max_v9_elements);


	return 1;

} // End of Init_v9

static void sf_markstate(struct ip_mc_list *pmc)
{
	struct ip_sf_list *psf;
	int mca_xcount = pmc->sfcount[MCAST_EXCLUDE];

	for (psf = pmc->sources; psf; psf = psf->sf_next)
		if (pmc->sfcount[MCAST_EXCLUDE]) {
			psf->sf_oldin = mca_xcount ==
				psf->sf_count[MCAST_EXCLUDE] &&
				!psf->sf_count[MCAST_INCLUDE];
		} else
			psf->sf_oldin = psf->sf_count[MCAST_INCLUDE] != 0;
}

